#!/bin/bash
# Kelvora cyberpunk v2: hover robot + direct scroll + bird-view. Project root madhe run kara (junya v1 var pan chalto).
set -e
[ -f src/JourneyScene.js ] || { [ -f kelvora/src/JourneyScene.js ] && cd kelvora; }
[ -f src/JourneyScene.js ] || { echo "ERROR: kelvora project folder sapadla nahi. 'cd' karun project root madhe ja."; exit 1; }
B=.bak_cyber_$(date +%H%M%S); mkdir -p "$B/src/office"
cp src/JourneyScene.js src/journeyTL.js src/Theme.js src/style.css "$B/src/"
cp src/office/rooms.js src/office/office.js src/office/agents.js "$B/src/office/"
cp index.html "$B/"
echo '' | base64 -d | tar xzf -
grep -q 'cyberpunk-v3' src/style.css || cat .v3.css >> src/style.css
grep -q 'cyberpunk-v4' src/style.css || cat .v4.css >> src/style.css
rm -f .v3.css .v4.css
echo "Done. Backup: $B  |  ata chalva: npm run dev"